def unzip(path, pathFolder):

    try:

        # descompacta o arquivo
        z = ZipFile(path, 'r')
        z.extractall(pathFolder)
        z.close()

        print("Arquivo descompactado com sucesso!")

    except:
        print("Houve um erro ao tentar descompactar o arquivo")

